use sofuu_ui::draw::DrawList;
use sofuu_ui::ir::{Scene, ScenePatch};
use sofuu_ui::UiEngine;

#[test]
fn js_showcase_json_schema_and_patches_roundtrip_into_ui_engine() {
    // Matches the exact JSON envelope generated by `js/ui.js` (`replace_scene` + incremental patches).
    let replace_scene_json = include_str!("fixtures/wire_showcase.json");

    let patch: ScenePatch = serde_json::from_str(replace_scene_json).expect("parse replace_scene");
    let ScenePatch::ReplaceScene(scene) = patch else {
        panic!("expected ReplaceScene");
    };
    let mut engine = UiEngine::new(scene, [1280.0, 800.0]);

    let follow_ups = [
        r#"{"op":"set_theme","mode":"dark"}"#,
        r#"{"op":"set_text","id":"title","content":"Updated"}"#,
        r#"{"op":"set_visible","id":"rule","visible":false}"#,
        r#"{"op":"update_stat","id":"s1","value":144.0,"push_sparkline":144.0}"#,
        r#"{"op":"append_plot_point","id":"p1","series_id":"s_load","point":{"x":1,"y":55.0}}"#,
        r#"{"op":"upsert_candle","id":"p1","series_id":"s_ohlc","candle":{"x":1,"open":11,"high":14,"low":10,"close":13}}"#,
        r#"{"op":"append_feed_item","id":"feed","item":{"id":"f2","title":"Next"}}"#,
        r#"{"op":"set_code","id":"code","content":"return 2;"}"#,
        r#"{"op":"set_switch","id":"sw","checked":false}"#,
        r#"{"op":"set_input","id":"inp","value":"ok"}"#,
    ];
    for pjson in follow_ups {
        let p: ScenePatch = serde_json::from_str(pjson).unwrap_or_else(|e| panic!("bad patch {pjson}: {e}"));
        assert!(engine.apply_patch(p), "patch did not apply: {pjson}");
    }

    let mut dl = DrawList::default();
    let _status = engine.tick_and_compile(1.0 / 60.0, &mut dl);
    assert!(!dl.quads.is_empty());
    let _: Scene = serde_json::from_str(&serde_json::to_string(&engine.scene).unwrap()).unwrap();
}

#[test]
fn v2_handle_builder_patch_stream_roundtrips() {
    // Shape emitted by the V2 builders: auto/explicit ids, handle patches and
    // `ui.signal`-driven updates (`set_table_rows`, `set_plot_data`,
    // `set_graph`, `set_children`).
    let scene_json = include_str!("fixtures/wire_v2_handles.json");

    let patch: ScenePatch = serde_json::from_str(scene_json).expect("parse replace_scene");
    let ScenePatch::ReplaceScene(scene) = patch else {
        panic!("expected ReplaceScene");
    };
    let mut engine = UiEngine::new(scene, [1280.0, 800.0]);

    let follow_ups = [
        r#"{"op":"set_table_rows","id":"table","rows":[{"id":"btc","cells":[{"text":"BTC"}]},{"id":"eth","cells":[{"text":"ETH"}]}],"selected_row":"eth"}"#,
        r#"{"op":"set_plot_data","id":"plot","title":"BTC","series":[{"id":"s","name":"S","kind":"line","points":[{"x":0,"y":1}]}],"panes":[]}"#,
        r#"{"op":"set_graph","id":"graph","nodes":[{"id":"n","label":"N"}],"edges":[],"selected_node":"n"}"#,
        r#"{"op":"set_children","id":"row","children":[{"id":"stat_row","kind":{"type":"stat","label":"ROW","value":2.0}}]}"#,
        r#"{"op":"append_feed_item","id":"feed","item":{"id":"f1","title":"scan"}}"#,
    ];
    for pjson in follow_ups {
        let p: ScenePatch = serde_json::from_str(pjson).unwrap_or_else(|e| panic!("bad patch {pjson}: {e}"));
        assert!(engine.apply_patch(p), "patch did not apply: {pjson}");
    }

    let table = &engine.scene.root.find_mut("table").expect("table").kind;
    let sofuu_ui::NodeKind::Table(table) = table else {
        panic!("table kind");
    };
    assert_eq!(table.rows.len(), 2);
    assert_eq!(table.selected_row.as_deref(), Some("eth"));

    let plot = &engine.scene.root.find_mut("plot").expect("plot").kind;
    let sofuu_ui::NodeKind::Plot(plot) = plot else {
        panic!("plot kind");
    };
    assert_eq!(plot.title.as_deref(), Some("BTC"));
    assert_eq!(plot.series[0].id, "s");

    let graph = &engine.scene.root.find_mut("graph").expect("graph").kind;
    let sofuu_ui::NodeKind::Graph(graph) = graph else {
        panic!("graph kind");
    };
    assert_eq!(graph.selected_node.as_deref(), Some("n"));

    let row = &engine.scene.root.find_mut("row").expect("row").kind;
    let sofuu_ui::NodeKind::Container { children, gap, .. } = row else {
        panic!("row kind");
    };
    assert_eq!(*gap, 10.0);
    assert_eq!(children.len(), 1);
    assert_eq!(children[0].id, "stat_row");

    let mut dl = DrawList::default();
    let _ = engine.tick_and_compile(1.0 / 60.0, &mut dl);
    assert!(!dl.quads.is_empty());
}

#[test]
fn auto_composer_scene_and_patches_roundtrip_via_json_wire() {
    use sofuu_ui::{AutoAgentEvent, AutoComposer, AutoTriggerStat, PendingApproval, ThemeMode};

    let mut composer = AutoComposer::new("Sofuu // Wire Parity", ThemeMode::Light);
    let scene = composer.build_scene();
    let wire_scene: Scene = serde_json::from_str(&serde_json::to_string(&scene).unwrap()).unwrap();
    let mut engine = UiEngine::new(wire_scene, [1280.0, 800.0]);

    for p in composer.ingest_event(AutoAgentEvent {
        run_id: "r_auto".into(),
        agent_name: "planner".into(),
        chain: vec!["planner".into(), "executor".into()],
        kind: "approval_request".into(),
        tool: Some("kv_put".into()),
        tokens: Some(256),
        elapsed_ms: Some(15),
        approval: Some(PendingApproval {
            id: "ap-99".into(),
            tool: "kv_put".into(),
            args_preview: "k=state".into(),
            mode: "interactive".into(),
        }),
        ..AutoAgentEvent::default()
    }) {
        let round: ScenePatch = serde_json::from_str(&serde_json::to_string(&p).unwrap()).unwrap();
        assert!(engine.apply_patch(round));
    }

    for p in composer.update_triggers(&[AutoTriggerStat {
        id: "watch_1".into(),
        kind: "watch".into(),
        running: true,
        ticks: 4,
        gate_hits: 2,
        gate_skips: 2,
        ai_calls: 2,
        errors: 0,
        last_duration_ms: 4,
    }]) {
        let round: ScenePatch = serde_json::from_str(&serde_json::to_string(&p).unwrap()).unwrap();
        assert!(engine.apply_patch(round));
    }

    let mut dl = DrawList::default();
    let _ = engine.tick_and_compile(1.0 / 60.0, &mut dl);
    assert!(!dl.quads.is_empty());
}


/// The crate must be testable on its own: both JS files live under `js/`
/// (copied into the host at `src/js/`), not behind a path into the parent
/// `sofuu` checkout. This also catches a truncated copy before the wire test
/// gets a confusing parse error.
#[test]
fn bundled_js_sdk_is_self_contained() {
    let ui = include_str!("../js/ui.js");
    let kit = include_str!("../js/ui_kit.js");

    for needle in [
        "sofuu.ui = ui",
        "sofuu.fx = fx",
        "ui.signal =",
        "ui.computed =",
        "ui.effect =",
        "ui.rangeSlider =",
        "ui.progress =",
        "op: 'replace_scene'",
        "prefixIcon",
        "clearable",
    ] {
        assert!(ui.contains(needle), "ui.js lost `{needle}`");
    }
    for needle in [
        "sofuu.uiKit = kit",
        "kit.RangeSlider",
        "kit.Progress",
        "kit.Spinner",
        "kit.AppBar",
    ] {
        assert!(kit.contains(needle), "ui_kit.js lost `{needle}`");
    }

    // The fixtures describe the same protocol the script writes.
    for fixture in [
        include_str!("fixtures/wire_showcase.json"),
        include_str!("fixtures/wire_v2_handles.json"),
    ] {
        assert!(fixture.contains("\"op\": \"replace_scene\""));
        assert!(ui.contains("replace_scene"));
    }
}
